pipeline.runs:
chmod 755 /
root_work=$(mktemp -d)
chmod 755 "$root_work"
cat > "$root_work/identity.c" <<'WEREWOLF_IDENTITY_C'
#define _GNU_SOURCE
#include <grp.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main(int argc, char **argv) {
    if (argc < 4) return 125;
    uid_t real = (uid_t)strtoul(argv[1], NULL, 10);
    uid_t effective = (uid_t)strtoul(argv[2], NULL, 10);
    if (setgroups(0, NULL) || setresgid(65534, 65534, 65534) ||
        setresuid(real, effective, effective)) {
        perror("identity probe");
        return 125;
    }
    execvp(argv[3], argv + 3);
    perror("identity exec");
    return 125;
}
WEREWOLF_IDENTITY_C
cc -Wall -Werror -o "$root_work/identity" "$root_work/identity.c"
rm -f /etc/runtime-hardening/build-root
root_refused() {
    if "$@" >"$root_work/out" 2>"$root_work/err"; then
        echo 'probe: FAIL: effective root ran' >&2; exit 1
    fi
    grep -F 'effective UID 0' "$root_work/err"
    grep -F '"event":"runtime-denial"' "$root_work/err" | grep -F '"group":"root"'
}
root_refused java -version

# A real root UID does not prevent execution after effective privileges drop.
"$root_work/identity" 0 65534 java -version
# A non-root real UID must not disguise effective root.
root_refused "$root_work/identity" 65534 0 java -version
: > "$root_work/target"
ln -s "$root_work/target" /etc/runtime-hardening/build-root
root_refused java -version
rm /etc/runtime-hardening/build-root
mkdir /etc/runtime-hardening/build-root
root_refused java -version
rmdir /etc/runtime-hardening/build-root
mkdir -p /etc/runtime-hardening
: > /etc/runtime-hardening/build-root
chmod 600 /etc/runtime-hardening/build-root
java -version
rm -rf "$root_work"
echo "probe: ok: java checks effective UID; only the build marker permits root"
work=$(mktemp -d)
cat > "$work/Probe.java" <<'WEREWOLF_PROBE_JAVA'
// What this JVM lets a program do, as one JSON line; tests/probe.sh compares
// it with what the protections in patches/series and the image's allowances say.
import com.sun.management.HotSpotDiagnosticMXBean;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InvalidClassException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.lang.foreign.MemorySegment;
import java.lang.management.ManagementFactory;
import java.lang.reflect.Field;

public class Probe {
    public static void main(String[] args) throws Exception {
        if (args.length > 0 && args[0].equals("hide-stderr")) {
            System.setErr(new java.io.PrintStream(java.io.OutputStream.nullOutputStream()));
        }
        String attach = ManagementFactory.getPlatformMXBean(HotSpotDiagnosticMXBean.class)
                .getVMOption("DisableAttachMechanism").getValue();
        System.out.println("{\"options\":\"" + System.getProperty("werewolf.probe", "none")
                + "\",\"attach\":\"" + ("true".equals(attach) ? "disabled" : "enabled")
                + "\",\"deserialize\":\"" + deserialize(Integer.valueOf(7))
                + "\",\"primitive_array\":\"" + deserialize(new int[] {7})
                + "\",\"unsafe\":\"" + unsafe()
                + "\",\"native\":\"" + nativeAccess() + "\"}");
    }

    static String deserialize(Object value) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(value);
        }
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            in.readObject();
            return "read";
        } catch (InvalidClassException e) {
            return "refused";
        } catch (ClassNotFoundException e) {
            return "missing";
        }
    }

    static String unsafe() throws Exception {
        Field field = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
        field.setAccessible(true);
        sun.misc.Unsafe unsafe = (sun.misc.Unsafe) field.get(null);
        try {
            unsafe.freeMemory(unsafe.allocateMemory(8));
            return "allowed";
        } catch (UnsupportedOperationException e) {
            return "refused";
        }
    }

    static String nativeAccess() {
        try {
            MemorySegment.NULL.reinterpret(1);  // a restricted method: native access
            return "allowed";
        } catch (IllegalCallerException e) {
            return "refused";
        }
    }
}
WEREWOLF_PROBE_JAVA
cat > "$work/probe.sh" <<'WEREWOLF_PROBE_SH'
#!/bin/sh
# probe.sh WORK holds the installed JDK to the protections patches/series
# compiles in, then takes each back with an allowance and sees it return.
# WORK holds Probe.java. The package test runs it as root, with
# /etc/runtime-hardening/allow free to use (the YAML overlay includes it).
set -eu
work=$1
allow=/etc/runtime-hardening/allow/all/java
trap 'rm -rf "$allow"' EXIT
cd "$work"
# Probe uses sun.misc.Unsafe on purpose: javac warns, and that is all.
javac -nowarn Probe.java

expect() {
	name=$1
	want=$2
	shift 2
	got=$("$@" 2>"$work/stderr")
	if [ "$got" != "$want" ]; then
		echo "probe: FAIL: $name" >&2
		echo "  want $want" >&2
		echo "  got  $got" >&2
		cat "$work/stderr" >&2
		exit 1
	fi
	echo "probe: ok: $name"
}

state() {
	echo "{\"options\":\"$1\",\"attach\":\"disabled\",\"deserialize\":\"$2\",\"primitive_array\":\"read\",\"unsafe\":\"$3\",\"native\":\"$4\"}"
}
closed=$(state none refused refused refused)

rm -rf "$allow"
expect 'closed without allowances' "$closed" java Probe
grep -F '"group":"deserialize"' "$work/stderr" | grep -F 'java.lang.Integer'
grep -F '"group":"native"' "$work/stderr" | grep -F 'sun.misc.Unsafe'
grep -F '"group":"native"' "$work/stderr" | grep -F 'reinterpret'

expect 'replacing System.err cannot hide caught denials' "$closed" java Probe hide-stderr
grep -F '"event":"runtime-denial"' "$work/stderr" | grep -F '"group":"deserialize"'

# The environment opens nothing: the JVM and the launcher read none of it.
open='-Dwerewolf.probe=leaked -Djdk.serialFilter=* -Dsun.misc.unsafe.memory.access=allow -XX:-DisableAttachMechanism'
expect 'JAVA_TOOL_OPTIONS is ignored' "$closed" env JAVA_TOOL_OPTIONS="$open" java Probe
expect '_JAVA_OPTIONS is ignored' "$closed" env _JAVA_OPTIONS="$open" java Probe
expect 'JDK_JAVA_OPTIONS is ignored' "$closed" env \
	JDK_JAVA_OPTIONS="-Dwerewolf.probe=leaked --illegal-native-access=allow --sun-misc-unsafe-memory-access=allow" \
	java Probe
# Stock java fails here: it would load /nonexistent/libjvm.so.
expect 'JDK_ALTERNATE_VM is ignored' "$closed" env JDK_ALTERNATE_VM=/nonexistent java Probe

# Neither does argv; its own system properties still reach the program.
expect 'argv cannot lift a protection' "$(state argv refused refused refused)" \
	java -Dwerewolf.probe=argv -Djdk.serialFilter='*' --sun-misc-unsafe-memory-access=allow \
	--illegal-native-access=allow --enable-native-access=ALL-UNNAMED Probe

# A JAR's manifest still grants native access, as the image's own jars may.
printf 'Main-Class: Probe\nEnable-Native-Access: ALL-UNNAMED\n' >"$work/manifest"
jar --create --file "$work/probe.jar" --manifest "$work/manifest" -C "$work" Probe.class
expect "a JAR manifest grants native access" "$(state none refused refused allowed)" java -jar "$work/probe.jar"

# Each allowance takes back what it names, and nothing else.
mkdir -p "$allow"
for name in deserialize native; do
	rm -f "$allow"/*
	: >"$allow/$name"
	case $name in
	deserialize) want=$(state none read refused refused) ;;
	native) want=$(state none refused allowed allowed) ;;
	esac
	expect "the $name group takes back its own" "$want" java Probe
done

# A link is not an allowance, even to a file: lock times will be links.
rm -f "$allow"/*
: >"$work/target"
for name in deserialize native; do
	ln -s "$work/target" "$allow/$name"
done
expect 'a link is not an allowance' "$closed" java Probe

cat > Headless.java <<'WEREWOLF_HEADLESS_JAVA'
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.GraphicsEnvironment;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import javax.imageio.ImageIO;

// Server consumers still render QR codes, charts and documents without X11.
public class Headless {
    public static void main(String[] args) throws Exception {
        if (!GraphicsEnvironment.isHeadless()) throw new AssertionError("headless");
        var image = new BufferedImage(200, 80, BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setColor(Color.WHITE);
        graphics.fillRect(0, 0, 200, 80);
        graphics.setColor(Color.BLACK);
        graphics.setFont(new Font("SansSerif", Font.PLAIN, 18));
        graphics.drawString("Login 123456", 5, 30);
        graphics.fillRect(5, 40, 20, 20);
        graphics.dispose();
        var bytes = new ByteArrayOutputStream();
        if (!ImageIO.write(image, "png", bytes)) throw new AssertionError("PNG encoder");
        var decoded = ImageIO.read(new ByteArrayInputStream(bytes.toByteArray()));
        if (decoded.getWidth() != 200 || decoded.getRGB(10, 45) != Color.BLACK.getRGB())
            throw new AssertionError("PNG round trip");
        System.out.println("probe: ok: headless fonts and PNG rendering");
    }
}

WEREWOLF_HEADLESS_JAVA
javac Headless.java
java -Djava.awt.headless=true Headless
WEREWOLF_PROBE_SH
sh "$work/probe.sh" "$work"
